pub fn putmask(a: Vec<f32>, mask: Vec<bool>, values: Vec<f32>) -> Vec<f32> {
    assert_eq!(
        a.len(),
        mask.len(),
        "mask length must equal input array length"
    );
    assert!(
        !values.is_empty(),
        "replacement values array must be non-empty"
    );

    let values_len = values.len();
    let mut result = Vec::with_capacity(a.len());

    for i in 0..a.len() {
        if mask[i] {
            result.push(values[i % values_len]);
        } else {
            result.push(a[i]);
        }
    }

    result
}